 }

-export function backoff(attempt: number, opts: RetryOptions = {}): number {
-  const base = opts.baseDelay ?? 100;
-  const delay = base * 2 ** attempt;
-  return Math.min(delay, opts.maxDelay ?? 30_000);
-}
+/**
+ * Full-jitter exponential backoff: delay is drawn uniformly from
+ * [0, base * 2**attempt), then clamped to maxDelay. Randomizing before
+ * clamping keeps the ceiling authoritative.
+ */
+export function backoff(attempt: number, opts: RetryOptions = {}): number {
+  const base = opts.baseDelay ?? 100;
+  const random = opts.random ?? Math.random;
+  const ceiling = base * 2 ** attempt;
+  const jittered = random() * ceiling;
+  return Math.min(jittered, opts.maxDelay ?? 30_000);
+}

diff --git a/test/backoff.test.ts b/test/backoff.test.ts
new file mode 100644
--- /dev/null
+++ b/test/backoff.test.ts
@@ -0,0 +1,43 @@
+import { test } from "node:test";
+import assert from "node:assert/strict";
+import { backoff } from "../src/retry.ts";
+
+/** Deterministic RNG so schedules are reproducible in CI. */
+function seeded(seed: number): () => number {
+  let s = seed;
+  return () => ((s = (s * 1103515245 + 12345) & 0x7fffffff) / 0x7fffffff);
+}
+
+test("spreads retries across the window", () => {
+  const rng = seeded(42);
+  const delays = Array.from({ length: 1000 }, () => backoff(4, { random: rng }));
+  const sorted = [...delays].sort((a, b) => a - b);
+  const p95 = sorted[Math.floor(sorted.length * 0.95)];
+  assert.ok(p95 > 1600 * 0.4, "p95 spread exceeds 40% of the window");
+});
+
+test("retries respect maxDelay ceiling", () => {
+  const rng = seeded(7);
+  for (let i = 0; i < 200; i++) {
+    assert.ok(backoff(9, { random: rng, maxDelay: 8000 }) <= 8000);
+  }
+});
